test_input = [
    [8, 8, 1, 1, 1, 1, 1, 1, 8],   # row 0
    [8, 8, 1, 8, 1, 8, 8, 8, 8],   # row 1
    [8, 8, 8, 8, 1, 8, 8, 8, 8],   # row 2
    [8, 8, 1, 8, 1, 8, 8, 1, 8],   # row 3
    [8, 8, 1, 8, 1, 8, 8, 1, 8],   # row 4
    [8, 8, 1, 8, 8, 8, 8, 1, 8],   # row 5
    [8, 8, 8, 8, 1, 8, 8, 8, 8],   # row 6
    [8, 8, 8, 8, 8, 8, 8, 8, 8],   # row 7
]

height = len(test_input)
width = len(test_input[0])

# Find all connected cells
all_component_ids = {}
component_id = 0

def get_component_id(r, c, grid, all_ids):
    if (r, c) in all_ids:
        return all_ids[(r, c)]

    # BFS to find all connected cells
    component = []
    stack = [(r, c)]
    while stack:
        cr, cc = stack.pop()
        if (cr, cc) not in all_ids:
            all_ids[(cr, cc)] = component_id
            component.append((cr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == 1:
                    if (nr, nc) not in all_ids:
                        stack.append((nr, nc))

    if len(component) > 1:
        component_id += 1
        all_ids[(r, c)] = component_id - 1
        return component_id - 1
    else:
        return component_id  # Isolated, gets incrementing ID starting from 0

# Process in order
for r in range(height):
    for c in range(width):
        if test_input[r][c] == 1:
            get_component_id(r, c, test_input, all_component_ids)

print("Component IDs for each alive cell:")
grid_ids = [[all_component_ids.get((r,c), -1) for c in range(width)] for r in range(height)]
for r in range(height):
    row_chars = []
    for c in range(width):
        if test_input[r][c] == 1:
            row_chars.append(str(grid_ids[r][c]) if grid_ids[r][c] != -1 else '.')
        else:
            row_chars.append('.')
    print(''.join(row_chars))

# Isolated cells are those that would be alone (component size 1)
# They should become 2
connected = set()
for r in range(height):
    for c in range(width):
        if test_input[r][c] == 1 and grid_ids[r][c] != -1:
            connected.add((r,c))

print(f"\n{len(connected)} cells connected to others as non-isolated")

# Let me manually trace to understand
