print(f"(3,7) value: {test_input[3][7]}")
print(f"(3,6) value: {test_input[3][6]}")
print(f"(3,8) value: {test_input[3][8]}")
print(f"(2,7) value: {test_input[2][7]}")
print(f"(4,7) value: {test_input[4][7]}")
print(f"Grid at (3,7):")
grid_section = test_input[2:5][2:8]
for row in grid_section:
    print(f"  {row[2:8]}")
